import { readFileSync } from 'node:fs'
import path from 'node:path'
import type { NextConfig } from 'next'

const repo = path.resolve(import.meta.dirname, '..')

// Desktop action modules -> page-side stand-ins that call the Worker
// (generated by scripts/gen-web-bridge.ts).
const actionAliases = JSON.parse(
  readFileSync(path.join(import.meta.dirname, 'actions', 'aliases.gen.json'), 'utf8'),
) as Record<string, string>

/**
 * The web edition: a static export — plain files on Cloudflare Pages, no
 * server of ours. It shares lib/ and components/ with the desktop build one
 * directory up; aliases swap out what a browser cannot run.
 */
// The app's place on its host: the landing page has the root (scripts/web-site.ts).
const base = process.env.WEB_BASE ?? '/app'

const config: NextConfig = {
  output: 'export',
  basePath: base,
  // Static hosts serve /pipeline/index.html for /pipeline.
  trailingSlash: true,
  images: { unoptimized: true },
  turbopack: {
    root: repo,
    resolveAlias: {
      ...actionAliases,
      // router.refresh() reloads the screens' data from the Worker.
      'next/navigation': './lib/navigation.ts',
      // Settings live in the browser, not in a config.json beside the database.
      '@/lib/settings': './lib/settings.ts',
      // drizzle's better-sqlite3 driver imports the native library to open a
      // path; the web edition always hands it the sqlite-wasm shim instead.
      'better-sqlite3': './lib/better-sqlite3-stub.ts',
      // The LinkedIn scraper never ships publicly.
      '#discover': '../lib/discover/stub.ts',
    },
  },
  env: {
    NEXT_PUBLIC_BUILD_ID: process.env.CVFORGE_BUILD_ID ?? String(Date.now()),
    // The web edition's name (lib/brand.ts); the desktop build keeps CVForge.
    NEXT_PUBLIC_BRAND: 'Rumbo',
    NEXT_PUBLIC_BASE: base,
  },
}

export default config
